CREATE SCHEMA IF NOT EXISTS teamville_demo;
SET search_path TO teamville_demo, public;
  
    CREATE TABLE IF NOT EXISTS workspaces (id TEXT PRIMARY KEY, token_hash TEXT UNIQUE NOT NULL, role TEXT NOT NULL CHECK(role IN ('school_admin','teacher','bursar','guardian')), expires_at TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS pupils (id TEXT NOT NULL, workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, admission TEXT NOT NULL, first_name TEXT NOT NULL, last_name TEXT NOT NULL, class_name TEXT NOT NULL, guardian TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Active', created_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'), PRIMARY KEY(workspace,id), UNIQUE(workspace,admission));
    CREATE TABLE IF NOT EXISTS attendance (workspace TEXT NOT NULL, student_id TEXT NOT NULL, school_date TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('Present','Absent','Late','Excused')), recorded_by TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'), PRIMARY KEY(workspace,student_id,school_date), FOREIGN KEY(workspace,student_id) REFERENCES pupils(workspace,id) ON DELETE CASCADE);
    CREATE TABLE IF NOT EXISTS scores (workspace TEXT NOT NULL, student_id TEXT NOT NULL, subject TEXT NOT NULL, ca INTEGER NOT NULL CHECK(ca BETWEEN 0 AND 40), exam INTEGER NOT NULL CHECK(exam BETWEEN 0 AND 60), state TEXT NOT NULL DEFAULT 'Draft' CHECK(state IN ('Draft','Submitted','Published')), version INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(workspace,student_id,subject), FOREIGN KEY(workspace,student_id) REFERENCES pupils(workspace,id) ON DELETE CASCADE);
    CREATE TABLE IF NOT EXISTS charges (id TEXT NOT NULL, workspace TEXT NOT NULL, student_id TEXT NOT NULL, category TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>0), PRIMARY KEY(workspace,id), FOREIGN KEY(workspace,student_id) REFERENCES pupils(workspace,id) ON DELETE CASCADE);
    CREATE TABLE IF NOT EXISTS payments (id TEXT NOT NULL, workspace TEXT NOT NULL, student_id TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>0), method TEXT NOT NULL, reference TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('Pending','Verified')), receipt TEXT, created_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'), PRIMARY KEY(workspace,id), UNIQUE(workspace,reference), UNIQUE(workspace,receipt), FOREIGN KEY(workspace,student_id) REFERENCES pupils(workspace,id) ON DELETE CASCADE);
    CREATE TABLE IF NOT EXISTS notices (id TEXT NOT NULL, workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, title TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'), PRIMARY KEY(workspace,id));
    CREATE TABLE IF NOT EXISTS activity (id TEXT PRIMARY KEY, workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, role TEXT NOT NULL, action TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'));
    CREATE TABLE IF NOT EXISTS result_versions (id TEXT PRIMARY KEY, workspace TEXT NOT NULL, student_id TEXT NOT NULL, snapshot TEXT NOT NULL, published_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'), FOREIGN KEY(workspace,student_id) REFERENCES pupils(workspace,id) ON DELETE CASCADE);
  

    CREATE TABLE IF NOT EXISTS midterm_scores (workspace TEXT NOT NULL, student_id TEXT NOT NULL, subject TEXT NOT NULL, score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100), state TEXT NOT NULL DEFAULT 'Draft' CHECK(state IN ('Draft','Submitted','Published')), PRIMARY KEY(workspace,student_id,subject), FOREIGN KEY(workspace,student_id) REFERENCES pupils(workspace,id) ON DELETE CASCADE);
    CREATE TABLE IF NOT EXISTS midterm_versions (id TEXT PRIMARY KEY, workspace TEXT NOT NULL, student_id TEXT NOT NULL, snapshot TEXT NOT NULL, published_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'), FOREIGN KEY(workspace,student_id) REFERENCES pupils(workspace,id) ON DELETE CASCADE);
    CREATE TABLE IF NOT EXISTS staff (workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, id TEXT NOT NULL, name TEXT NOT NULL, title TEXT NOT NULL, PRIMARY KEY(workspace,id));
    CREATE TABLE IF NOT EXISTS staff_payroll (workspace TEXT NOT NULL,staff_id TEXT NOT NULL,monthly_amount INTEGER NOT NULL CHECK(monthly_amount>0),PRIMARY KEY(workspace,staff_id),FOREIGN KEY(workspace,staff_id) REFERENCES staff(workspace,id) ON DELETE CASCADE);
    CREATE TABLE IF NOT EXISTS obligations (workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('Salary','Expense')),payee TEXT NOT NULL,staff_id TEXT,period TEXT,description TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),reference TEXT NOT NULL,requested_role TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Requested' CHECK(status IN ('Requested','Approved','Rejected','Paid')),approved_role TEXT,paid_at TEXT,voucher TEXT,created_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'),PRIMARY KEY(workspace,id),UNIQUE(workspace,reference),FOREIGN KEY(workspace,staff_id) REFERENCES staff(workspace,id));
    CREATE UNIQUE INDEX IF NOT EXISTS salary_once ON obligations(workspace,staff_id,period) WHERE kind='Salary' AND status!='Rejected';
    CREATE TABLE IF NOT EXISTS purse_funding (workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,id TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),category TEXT NOT NULL,reference TEXT NOT NULL,description TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'),PRIMARY KEY(workspace,id),UNIQUE(workspace,reference));
    CREATE TABLE IF NOT EXISTS staff_messages (workspace TEXT NOT NULL, id TEXT NOT NULL,staff_id TEXT NOT NULL,obligation_id TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US'),PRIMARY KEY(workspace,id),UNIQUE(workspace,obligation_id),FOREIGN KEY(workspace,staff_id) REFERENCES staff(workspace,id) ON DELETE CASCADE);
    CREATE TABLE IF NOT EXISTS disbursement_details (workspace TEXT NOT NULL,obligation_id TEXT NOT NULL,method TEXT NOT NULL,reference TEXT NOT NULL,paid_date TEXT NOT NULL,PRIMARY KEY(workspace,obligation_id),UNIQUE(workspace,reference),FOREIGN KEY(workspace,obligation_id) REFERENCES obligations(workspace,id) ON DELETE CASCADE);
  
